// Remove only files generated by earlier iOS diagnostic builds.
#import <Foundation/Foundation.h>
#include <unistd.h>
void Port0rCleanOldFiles(NSString *home) {
    NSFileManager *fm = NSFileManager.defaultManager;
    NSDictionary<NSString *, NSArray<NSString *> *> *oldFiles = @{
        @"Documents/Port0r-diagnostics": @[@"launch.log", @"launch.previous.log"],
        @"Documents/shimdump": @[@"lib1.bin", @"lib2.bin", @"lib3.bin"]
    };
    for (NSString *relative in oldFiles) {
        NSString *directory = [home stringByAppendingPathComponent:relative];
        NSDictionary *attributes = [fm attributesOfItemAtPath:directory error:nil];
        if ([attributes[NSFileType] isEqual:NSFileTypeSymbolicLink]) {
            [fm removeItemAtPath:directory error:nil]; // remove the alias, never follow it
            continue;
        }
        if (![attributes[NSFileType] isEqual:NSFileTypeDirectory]) continue;
        for (NSString *name in oldFiles[relative]) {
            NSString *file = [directory stringByAppendingPathComponent:name];
            NSString *kind = [fm attributesOfItemAtPath:file error:nil][NSFileType];
            if ([kind isEqual:NSFileTypeRegular] || [kind isEqual:NSFileTypeSymbolicLink])
                [fm removeItemAtPath:file error:nil];
        }
        rmdir(directory.fileSystemRepresentation); // succeeds only when empty; preserves unknown content
    }
}
